import{_ as e,o as a,c as r,a0 as o}from"./chunks/framework.D7EjqxMK.js";const _=JSON.parse('{"title":"成本优化策略","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/04_工程实践/02_成本优化策略.md","filePath":"06-agent/04_工程实践/02_成本优化策略.md"}'),n={name:"06-agent/04_工程实践/02_成本优化策略.md"};function i(s,t,l,d,h,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="成本优化策略" tabindex="-1">成本优化策略 <a class="header-anchor" href="#成本优化策略" aria-label="Permalink to &quot;成本优化策略&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块四 · 04_工程实践 · 第 2 节 <strong>难度</strong>：⭐⭐⭐ | <strong>前置知识</strong>：Agent 基础</p></blockquote><hr><h2 id="_1-五大优化策略" tabindex="-1">1. 五大优化策略 <a class="header-anchor" href="#_1-五大优化策略" aria-label="Permalink to &quot;1. 五大优化策略&quot;">​</a></h2><h3 id="_1-1-模型路由-按任务分级" tabindex="-1">1.1 模型路由（按任务分级） <a class="header-anchor" href="#_1-1-模型路由-按任务分级" aria-label="Permalink to &quot;1.1 模型路由（按任务分级）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>模型</th><th>成本/1M tokens</th><th>适用</th></tr></thead><tbody><tr><td>L1（简单，60-70%）</td><td>GPT-4o-mini / Claude Haiku</td><td>$0.15-0.50</td><td>简单任务</td></tr><tr><td>L2（中等，20-30%）</td><td>Claude Sonnet / GPT-4o</td><td>$3-15</td><td>中等任务</td></tr><tr><td>L3（复杂，5-10%）</td><td>GPT-4.5 / Claude Opus</td><td>$15-60</td><td>复杂推理</td></tr></tbody></table><h3 id="_1-2-缓存策略" tabindex="-1">1.2 缓存策略 <a class="header-anchor" href="#_1-2-缓存策略" aria-label="Permalink to &quot;1.2 缓存策略&quot;">​</a></h3><p>缓存是 Agent 成本优化中 ROI 最高的手段，可消除 20-45% 的 API 调用。<a href="https://agentwiki.org/caching_strategies_for_agents" target="_blank" rel="noreferrer">来源: AgentWiki - Caching Strategies for Agents</a></p><h3 id="_1-3-提示词优化" tabindex="-1">1.3 提示词优化 <a class="header-anchor" href="#_1-3-提示词优化" aria-label="Permalink to &quot;1.3 提示词优化&quot;">​</a></h3><p>Few-shot learning 可保持同等效果的同时减少 20-40% token 消耗。<a href="https://aitoolsbusiness.com/ai-cost-optimization/" target="_blank" rel="noreferrer">来源: AI Cost Optimization (AIToolsBusiness)</a></p><h3 id="_1-4-prompt-缓存" tabindex="-1">1.4 Prompt 缓存 <a class="header-anchor" href="#_1-4-prompt-缓存" aria-label="Permalink to &quot;1.4 Prompt 缓存&quot;">​</a></h3><p>企业环境中，prompt caching（复用系统 prompt 的 KV cache）可大幅降低重复请求成本。<a href="https://inductivee.com/blog/enterprise-llm-cost-optimization" target="_blank" rel="noreferrer">来源: Inductivee - LLM Cost Optimization</a></p><hr><h2 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h2><ul><li><a href="https://callsphere.ai/blog/ai-agent-cost-optimization-strategies-production.md" target="_blank" rel="noreferrer">AI Agent Cost Optimization: Strategies for Keeping Production Costs Under Control</a></li><li><a href="https://zylos.ai/research/2026-04-12-ai-agent-cost-optimization-token-budget-model-routing" target="_blank" rel="noreferrer">AI Agent Cost Optimization: Token Budgets, Model Routing, and Production FinOps (Zylos)</a></li><li><a href="https://optyxstack.com/cost-optimization/model-routing-for-cost-control-when-to-use-small-large-or-fallback-models" target="_blank" rel="noreferrer">Model Routing for Cost Control (OptyxStack)</a></li><li><a href="https://harnessengineering.academy/blog/reducing-ai-agent-inference-costs-caching-strategies-model-routing-and-token-optimization-techniques/" target="_blank" rel="noreferrer">Reducing AI Agent Inference Costs (Harness Engineering)</a></li><li><a href="https://aitoolsbusiness.com/ai-cost-optimization/" target="_blank" rel="noreferrer">AI Cost Optimization: Caching, Batching, Smaller Models</a></li></ul>',15)])])}const p=e(n,[["render",i]]);export{_ as __pageData,p as default};
